489	// fetchDockerHubTagsMeta fetches last_updated times from the Docker Hub public API.
490	// Works for public repos (no auth needed). Returns partial results on error.
491	func fetchDockerHubTagsMeta(namespace, repo string) (map[string]time.Time, error) {
492		endpoint := fmt.Sprintf("https://hub.docker.com/v2/repositories/%s/%s/tags?page_size=100&ordering=last_updated", namespace, repo)
493		req, err := http.NewRequest("GET", endpoint, nil)
494		if err != nil {
495			return nil, err
496		}
497		req.Header.Set("Accept", "application/json")
498		resp, err := ociHTTPClient.Do(req)
499		if err != nil {
500			return nil, err
501		}
502		defer func() { _ = resp.Body.Close() }()
503		if resp.StatusCode != http.StatusOK {
504			return nil, fmt.Errorf("hub API returned %d", resp.StatusCode)
505		}
506		body, err := io.ReadAll(resp.Body)
507		if err != nil {
508			return nil, err
509		}
510		var result struct {
511			Results []struct {
512				Name        string `json:"name"`
513				LastUpdated string `json:"last_updated"`
514			} `json:"results"`
515		}
516		if err := json.Unmarshal(body, &result); err != nil {
517			return nil, err
518		}
519		meta := make(map[string]time.Time, len(result.Results))
520		for _, r := range result.Results {
521			if t, err := time.Parse(time.RFC3339Nano, r.LastUpdated); err == nil {
522				meta[r.Name] = t
523			}
524		}
525		return meta, nil
526	}
527	
528	// loadMultiRegistryTagsMetaCmd fetches tag metadata for one registry in the background.
529	// For Docker Hub it uses the Hub API; other registries return empty (no error).
530	func loadMultiRegistryTagsMetaCmd(registryURL, repo string) tea.Cmd {
531		return func() tea.Msg {
532			base := strings.ToLower(strings.TrimSuffix(registryURL, "/"))
533			isDockerhub := base == "docker.io" || base == "registry-1.docker.io"
534			if !isDockerhub {
535				return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: nil, Err: nil}
536			}
537			parts := strings.SplitN(repo, "/", 2)
538			if len(parts) != 2 {
539				return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: nil, Err: nil}
540			}
541			meta, err := fetchDockerHubTagsMeta(parts[0], parts[1])
542			return MultiRegistryTagsMetaMsg{RegistryURL: registryURL, Repo: repo, Meta: meta, Err: err}
543		}
544	}
