554	// detectRegistryGroupCmd calls the generic registrymgr.DetectGroup to determine
555	// whether reg is a group repository and enumerate its members.
556	// Always emits RegistryGroupDetectedMsg (Members==nil means not a group).
557	func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
558		return func() tea.Msg {
559			ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
560			defer cancel()
561	
562			// Look up stored credentials for the Docker registry URL first.
563			storedUser, storedPass, _ := docker.GetStoredCreds(reg.URL)
564			username := reg.Username
565			if username == "" {
566				username = storedUser
567			}
568			if password == "" {
569				password = storedPass
570			}
571	
572			// When a ManagementURL is set, its host may differ from the Docker registry
573			// host. Docker stores credentials by hostname only, so extract just the
574			// scheme+host (strip the repository path) before looking up credentials.
575			if reg.ManagementURL != "" && password == "" {
576				mgmtLookup := reg.ManagementURL
577				if u, err := url.Parse(reg.ManagementURL); err == nil && u.Host != "" {
578					mgmtLookup = u.Scheme + "://" + u.Host
579				}
580				mgmtUser, mgmtPass, ok := docker.GetStoredCreds(mgmtLookup)
581				if ok {
582					if username == "" {
583						username = mgmtUser
584					}
585					password = mgmtPass
586				}
587			}
588	
589			info := registrymgr.RegistryInfo{
590				URL:           reg.URL,
591				ManagementURL: reg.ManagementURL,
592				Username:      username,
593				Password:      password,
594			}
595			members, err := registrymgr.DetectGroup(ctx, info)
596			return RegistryGroupDetectedMsg{RegistryURL: reg.URL, Members: members, Err: err}
597		}
598	}
