70	// View renders the browser for the current state.
71	func (b *RegistryBrowser) View() string {
72		switch b.state {
73		case browserStateResolving:
74			return b.viewResolving()
75		case browserStateTags:
76			return b.viewTags()
77		case browserStateStatus:
78			return b.viewStatus()
79		default:
80			return b.viewInput()
81		}
82	}
83	
84	func (b *RegistryBrowser) viewResolving() string {
85		return theme.EmptyLineBg(b.width) + "\n" +
86			theme.SpinnerMessage(b.spinner.View(), "Checking registries...")
87	}
88	
89	func (b *RegistryBrowser) viewInput() string {
90		var sb strings.Builder
91	
92		sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
93		sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
94		sb.WriteString("\n\n")
95	
96		if len(b.entries) > 0 {
97			sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
98			var currentGroup string
99			for i, entry := range b.entries {
100				if entry.ParentAlias != "" && entry.ParentAlias != currentGroup {
101					if currentGroup != "" {
102						sb.WriteString("\n")
103					}
104					currentGroup = entry.ParentAlias
105					sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render(currentGroup+":") + "\n")
106				} else if entry.ParentAlias == "" && currentGroup != "" {
107					currentGroup = ""
108					sb.WriteString("\n")
109				}
110				label := entry.Alias
111				if entry.ParentAlias != "" {
112					label = "  " + entry.Alias // visual indent for group members
113				}
114				checked := b.selectedRegs[entry.URL]
115				focused := b.focusedField == b.brFieldReg(i)
116				sb.WriteString(theme.RenderCheckbox(checked, label, focused))
117				if i < len(b.entries)-1 {
118					sb.WriteString("\n")
119				}
120			}
121			sb.WriteString("\n\n")
122		}
123	
124		sb.WriteString("  ")
125		sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))
126	
127		return sb.String()
128	}
129	
130	func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
131		var labelStr string
132		if b.focusedField == fieldIdx {
133			labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
134		} else {
135			labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
136		}
137		return labelStr + "\n  " + value
138	}
