152	// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
153	func (b *RegistryBrowser) FilterIsVisible() bool {
154		return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || b.registryFilter != "")
155	}
