}

// renderStartButton renders the start scan button
func (m Model) renderStartButton() string {
	canStart := m.deps.TrivyAvailable || m.deps.GitleaksAvailable
	if !canStart {
		return theme.DimStyle.Render("[ No scanners available ]")
	}
