5		"errors"
6		"sort"
7		"strings"
8		"sync"
9		"testing"
10	)
11	
12	// Scan runs its stages concurrently against one runner, so a test says what
13	// each stage answers rather than what the next call answers.
14	
15	type stageReply struct {
16		stdout string
17		err    error
18	}
19	
20	// stageOf names the stage an invocation belongs to, from the invocation alone —
21	// which is the only thing the runner sees.
22	func stageOf(tc toolCmd) string {
23		s := tc.String()
24		switch {
25		case strings.Contains(s, "cyclonedx"):
26			return "sbom"
27		case strings.Contains(s, "--scanners license"):
28			return "license"
29		case strings.Contains(s, "--scanners misconfig"):
30			return "misconfig"
31		case strings.HasPrefix(s, "gitleaks"):
32			return "secret"
33		default:
34			return "vuln"
35		}
36	}
37	
38	func byStage(t *testing.T, replies map[string]stageReply) *scriptedRunner {
39		t.Helper()
40		r := &scriptedRunner{}
41		r.reply = func(tc toolCmd) ([]byte, error) {
42			stage := stageOf(tc)
43			reply, scripted := replies[stage]
44			if !scripted {
45				t.Errorf("the %s stage ran although nothing was scripted for it: %s", stage, tc)
46			}
47			return []byte(reply.stdout), reply.err
48		}
49		useRunner(t, r)
50		return r
51	}
52	
53	// stagesRun reports which stages the runner was actually asked to execute.
54	func stagesRun(r *scriptedRunner) []string {
55		r.mu.Lock()
56		defer r.mu.Unlock()
57		seen := make([]string, 0, len(r.calls))
58		for _, c := range r.calls {
59			seen = append(seen, stageOf(c))
60		}
61		sort.Strings(seen)
62		return seen
63	}
64	
65	func everyTool() DependencyStatus {
66		return DependencyStatus{
67			TrivyAvailable:    true,
68			TrivySource:       ToolSourceBinary,
69			TrivyImage:        DefaultTrivyImage,
70			GitleaksAvailable: true,
71			GitleaksSource:    ToolSourceBinary,
72			GitleaksImage:     DefaultGitleaksImage,
73			DockerAvailable:   true,
74		}
75	}
76	
77	func everyStage() ScanOptions {
78		return ScanOptions{
79			EnableVuln:      true,
80			EnableSecret:    true,
81			EnableLicense:   true,
82			EnableMisconfig: true,
83			GenerateSBOM:    true,
84		}
85	}
86	
87	// recorder collects progress from the scan goroutines.
88	type recorder struct {
89		mu      sync.Mutex
90		updates []ProgressUpdate
91	}
92	
93	func (rec *recorder) fn() func(ProgressUpdate) {
94		return func(u ProgressUpdate) {
95			rec.mu.Lock()
96			defer rec.mu.Unlock()
97			rec.updates = append(rec.updates, u)
98		}
99	}
100	
101	// statusOf returns the transitions reported for one stage, in order. A running
102	// update carrying a detail is the tool talking, not a transition, so it is left
103	// out — otherwise every line of a database download would read as a state
104	// change.
105	func (rec *recorder) statusOf(stage string) []StageStatus {
106		rec.mu.Lock()
107		defer rec.mu.Unlock()
108		var out []StageStatus
109		for _, u := range rec.updates {
110			if u.Stage != stage || (u.Status == StageRunning && u.Detail != "") {
111				continue
112			}
113			out = append(out, u.Status)
114		}
115		return out
116	}
117	
118	func licenseReport(t *testing.T) string {
119		t.Helper()
120		return trivyReport(t, TrivyResult{Licenses: []TrivyLicense{
121			{Name: "GPL-3.0", Category: "restricted", PkgName: "somelib", Severity: "MEDIUM", FilePath: "go.mod"},
122		}})
123	}
124	
