17	// trivyReport is what the fake trivy prints. Two severities are enough to prove
18	// the counts are read per-severity rather than totalled.
19	const trivyReport = `{"Results":[{"Target":"api:v1","Vulnerabilities":[
20		{"VulnerabilityID":"CVE-1","Severity":"CRITICAL","PkgName":"openssl","InstalledVersion":"3.0.1"},
21		{"VulnerabilityID":"CVE-2","Severity":"HIGH","PkgName":"zlib","InstalledVersion":"1.2.11"},
22		{"VulnerabilityID":"CVE-3","Severity":"HIGH","PkgName":"curl","InstalledVersion":"8.0.0"}
23	]}]}`
