37	// The whole point of the cache is that a second visit costs nothing, so the
38	// scan has to leave both halves behind: the counts the row shows and the report
39	// Enter reads (Rule 126).
40	func TestAScanLeavesItsCountsAndItsFullReportOnDisk(t *testing.T) {
41		installFakeTrivy(t, trivyReport)
42	
43		msgs := testutil.Msgs(scanOneImageCmd(
44			imageScanJob{Name: "api:v1", Target: "api:v1"}, vulnScan(), make(chan struct{}, 1)))
45	
46		if len(msgs) != 2 {
47			t.Fatalf("got %d messages, want a start and a finish", len(msgs))
48		}
49		if start, ok := msgs[0].(ImageScanStartingMsg); !ok || start.ImageName != "api:v1" {
50			t.Fatalf("msgs[0] = %#v, want the scan announcing itself first", msgs[0])
51		}
52		done, ok := msgs[1].(ImageScanFinishedMsg)
53		if !ok {
54			t.Fatalf("msgs[1] = %#v, want ImageScanFinishedMsg", msgs[1])
55		}
56		if done.Err != nil {
57			t.Fatalf("Err = %v, want a scan that produced a report", done.Err)
58		}
59		if done.Entry.Critical != 1 || done.Entry.High != 2 {
60			t.Errorf("Entry = %+v, want 1 critical and 2 high", done.Entry)
61		}
62	
63		cached, err := cache.NewImageScanCache()
64		if err != nil {
65			t.Fatalf("reopening the scan cache: %v", err)
66		}
67		t.Cleanup(func() { _ = cached.Delete("api:v1") })
68		entry := cached.Get("api:v1")
69		if entry == nil || entry.Critical != 1 {
70			t.Errorf("the cache holds %+v, want the counts that were just reported", entry)
71		}
72	
73		result, err := cache.LoadImageScanResult("api:v1")
74		if err != nil {
75			t.Fatalf("the full report was not saved: %v", err)
76		}
77		if len(result.Findings) != 3 {
78			t.Errorf("the saved report has %d findings, want all three", len(result.Findings))
79		}
80	}
