93		if done.ImageName != "orphan" {
94			t.Errorf("ImageName = %q, want the name the table shows", done.ImageName)
95		}
96		t.Cleanup(func() {
97			if c, err := cache.NewImageScanCache(); err == nil {
98				_ = c.Delete("orphan")
99			}
100		})
101	
102		var scanned string
103		for _, line := range invocations() {
104			if strings.HasPrefix(line, "trivy image") {
105				scanned = line
106			}
107		}
108		if scanned == "" {
109			t.Fatalf("trivy was never asked to scan an image; invocations: %v", invocations())
110		}
