116	// D20, asserted inverted: this pins the defect, not the behaviour that is
117	// wanted. With no trivy installed, Scan() skips the stage entirely rather than
118	// failing it, so the result carries no errors and no findings — and
119	// scanOneImageCmd only reports a failure when there are errors *and* no
120	// findings. The image is therefore recorded as clean, cached with a fresh
121	// timestamp, and Rule 126 keeps it that way until an explicit rescan.
122	//
123	// This view has no dependency check at all, unlike the security view
124	// (view.go:147, `canStart := m.deps.TrivyAvailable || m.deps.GitleaksAvailable`),
125	// so nothing upstream catches it either.
126	//
127	// When D20 is fixed, this test is what fails: turn it into
128	// TestAScanWithNoScannerInstalledIsReportedAsAFailure.
129	func TestAScanWithNoScannerInstalledIsWronglyReportedAsClean(t *testing.T) {
130		noDocker(t) // an empty PATH: no trivy, no gitleaks, no docker either
131	
132		msgs := testutil.Msgs(scanOneImageCmd(
133			imageScanJob{Name: "no-scanner:v1", Target: "no-scanner:v1"}, vulnScan(), make(chan struct{}, 1)))
134	
135		done := msgs[len(msgs)-1].(ImageScanFinishedMsg)
136		t.Cleanup(func() {
137			if c, err := cache.NewImageScanCache(); err == nil {
138				_ = c.Delete("no-scanner:v1")
139			}
140		})
141	
142		if done.Err != nil {
143			t.Fatalf("Err = %v — D20 appears fixed; see the comment above", done.Err)
144		}
145		if done.Entry.Critical != 0 || done.Entry.High != 0 {
146			t.Errorf("Entry = %+v, want the empty counts the defect produces", done.Entry)
147		}
148	
149		// The damaging half: the empty result reaches the disk, so the row keeps
150		// claiming the image is clean after a restart.
151		cached, err := cache.NewImageScanCache()
152		if err != nil {
153			t.Fatalf("reopening the scan cache: %v", err)
154		}
155		if entry := cached.Get("no-scanner:v1"); entry == nil {
156			t.Error("nothing was cached — D20 appears fixed; see the comment above")
157		}
158	}
