160	// The batch is what ctrl+a and the "scan all" path emit. Every image has to be
161	// announced and answered for, or a row keeps its spinner forever.
162	func TestABatchAnnouncesAndAnswersForEveryImage(t *testing.T) {
163		installFakeTrivy(t, `{"Results":[]}`)
164	
165		jobs := []imageScanJob{
166			{Name: "api:v1", Target: "api:v1"},
167			{Name: "cache:v2", Target: "cache:v2"},
168		}
169		msgs := testutil.Msgs(batchScanCmd(jobs, vulnScan()))
170		t.Cleanup(func() {
171			if c, err := cache.NewImageScanCache(); err == nil {
172				for _, job := range jobs {
173					_ = c.Delete(job.Name)
174				}
175			}
176		})
177	
178		started, finished := map[string]bool{}, map[string]bool{}
179		for _, msg := range msgs {
180			switch m := msg.(type) {
181			case ImageScanStartingMsg:
182				started[m.ImageName] = true
183			case ImageScanFinishedMsg:
184				finished[m.ImageName] = true
185			}
186		}
187		for _, job := range jobs {
188			if !started[job.Name] {
189				t.Errorf("%s was scanned without announcing itself", job.Name)
190			}
191			if !finished[job.Name] {
192				t.Errorf("%s never reported a result", job.Name)
193			}
194		}
195	}
